def retrieve_broad(query):
    # broad first round context
    return "Falcon plan overview: includes hosting, support, and ten projects."

def retrieve_specific(query, prior_context):
    # narrower follow-up round
    if "cost" in query.lower():
        return "Falcon plan pricing: twenty dollars per month."
    return "No further specific detail found."

def recursive_rag(query, max_rounds=3):
    # stop once no further specific detail is found
    context = retrieve_broad(query)
    rounds_run = 1
    for round_num in range(2, max_rounds + 1):
        new_context = retrieve_specific(query, context)
        if new_context == "No further specific detail found.":
            break
        context = new_context
        rounds_run += 1
    return {"rounds_run": rounds_run, "final_context": context}

result = recursive_rag("What does the Falcon plan cost?")
print("Recursive RAG result:")
print(result)
